}
export function encode(v: number[]) {
  return v.reduceRight((s, d) => s * 3 + d, 0);
}
export function vectorAdd(a: number[], b: number[], sign = 1) {
  return a.map((x, i) => (x + sign * b[i] + 3) % 3);
}
