    throw Error("La suma debe ser 2^n, n ≤40.");
  const vectors = ternaryVectors(k),
    dot = (a: number[], b: number[]) =>
      a.reduce((s, x, i) => s + x * b[i], 0) % 3;
  const projections = vectors.map((x) => {
    const row = [0, 0, 0];
    vectors.forEach((s, i) => (row[dot(x, s)] += counts[i]));
    let f = Infinity;
    for (let v of row)
      if (v) {
        let z = 0;
        while (v % 2 === 0) {
          v /= 2;
          z++;
        }
        f = Math.min(f, z);
      }
    return { x, row, f };
  });
