  const mass = (generators: number[][]) => {
    const h = projections.filter((p) =>
      generators.every((g) => dot(p.x, g) === 0),
    );
    return ((3 * h.reduce((s, p) => s + p.f, 0)) / h.length - n) / 2;
  };
