import { event, type TraceEvent } from "./trace";
export type TrackState = {
  cells: { x: number; y: number; d: number; piece: string }[];
  x: number;
  y: number;
  d: number;
  used: string;
};
export function checkTrack(track: string, trace = false) {
  const events: TraceEvent<TrackState>[] = [],
    seen = new Set<string>();
